def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Each line is split at its first "=", so values may themselves contain "=".
    Whitespace around the name and around the value is stripped. Lines without
    "=" are ignored. Key matching is exact and case-sensitive. If the key
    appears more than once, the first matching line wins. Returns "" when the
    key is absent (or present with an empty value). Never reads files.
    """
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    text = "a=1\nb=2\nc=3"
    assert config_value(text, "a") == "1"
    assert config_value(text, "b") == "2"
    assert config_value(text, "c") == "3"


def test_absent_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  hello world  \n", "name") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\n\na=1\nmore junk", "a") == "1"
    assert config_value("junk", "junk") == ""


def test_key_match_is_exact() -> None:
    text = "ab=1\nA=2\na_=3"
    assert config_value(text, "a") == ""
    assert config_value(text, "ab") == "1"
    assert config_value(text, "A") == "2"


def test_empty_value_returns_empty_string() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_value_not_confused_with_key() -> None:
    assert config_value("a=b\nb=c", "b") == "c"
